import type { EvaluationEvidence } from "@/server/ai/final-evaluation/aggregate";
import { MODE_LABELS, MODE_INSTRUCTIONS } from "@/prompts/mode";

/**
 * ROLE / INPUT / TASK / CONSTRAINTS / OUTPUT FORMAT prompt for the final
 * evaluation narrative. This is the ONLY text generated by Gemini for the
 * report: every score, topic score, strength, knowledge gap, improvement
 * question, and difficulty rating is computed deterministically elsewhere.
 * Gemini summarizes that structured evidence; it never decides scores.
 */

const SYSTEM_PROMPT = [
  "ROLE",
  "You are a senior AI engineering lead writing a final candidate-facing evaluation for an adaptive technical interview. Your text is shown directly to the candidate, so be specific, constructive, and encouraging — never condescending.",
  "{mode}",
  "TASK",
  "From the structured evidence provided, write:",
  "1. summary — 2-4 sentences summarizing overall performance.",
  "2. topicSummaries — one 1-2 sentence summary per topic, using the exact topic names provided. Omit no topic; add none.",
  "3. adaptiveBehavior — 1-3 sentences on how the candidate responded as the interview adapted to their answers.",
  "4. recommendations — exactly 3-5 specific, actionable next steps grounded in the evidence.",
  "RULES",
  "- Base every sentence ONLY on the provided evidence. Do not invent topics, scores, behaviors, or facts.",
  "- Do not mention confidence values, internal scoring, the interviewer's reasoning, or any hidden/AI systems.",
  "- If a topic has no summary provided, do not write about it.",
  "- For DSA Friendly mode, never penalize the candidate for not reaching advanced questions; emphasize reasoning, approach, and improvement after support.",
  "OUTPUT FORMAT",
  "Return ONLY a single JSON object matching exactly this shape:",
  JSON.stringify({
    summary: "A concise 2-4 sentence overall summary.",
    topicSummaries: [{ topic: "Exact topic name", summary: "1-2 sentence summary" }],
    adaptiveBehavior: "1-3 sentences on how the candidate responded to adaptation.",
    recommendations: ["Actionable next step 1", "Actionable next step 2", "Actionable next step 3"],
  }),
  "Do not include prose or markdown fences.",
].join("\n");

function formatProgression(evidence: EvaluationEvidence): string {
  return evidence.progression
    .map((entry) => `${entry.difficulty}: ${entry.performance}${entry.questionsAsked > 0 ? ` (${entry.questionsAsked} question${entry.questionsAsked === 1 ? "" : "s"})` : ""}`)
    .join(" | ");
}

function sampleExcerpts(evidence: EvaluationEvidence): string {
  const scored = evidence.records.map((record, index) => ({ ...record, index }));
  const best = [...scored].sort((a, b) => b.score - a.score).slice(0, 2);
  const worst = [...scored].sort((a, b) => a.score - b.score).slice(0, 2);
  const picks = [...best, ...worst].sort((a, b) => a.index - b.index);

  return picks
    .map(
      (pick) =>
        `- Q: ${pick.prompt.slice(0, 240)}\n  A: ${pick.answer.slice(0, 300)}`
    )
    .join("\n");
}

export function buildFinalEvaluationPrompt(input: EvaluationEvidence): { system: string; user: string } {
  const mode = input.mode;
  const user = [
    "STRUCTURED EVIDENCE (authoritative — do not contradict it)",
    `Candidate: ${input.candidate.name}`,
    `Mode: ${MODE_LABELS[mode]}`,
    `Overall score: ${input.overallScore}/100 (readiness: ${input.readiness})`,
    "",
    "Topic performance (score /100, questions asked):",
    ...input.topics.map(
      (topic) => `- ${topic.topic}: ${topic.score}/100, ${topic.questionsAsked} question${topic.questionsAsked === 1 ? "" : "s"}`
    ),
    "",
    "Difficulty progression:",
    formatProgression(input),
    "",
    `Observed strengths: ${input.strengths.length > 0 ? input.strengths.join("; ") : "none observed"}`,
    `Knowledge gaps: ${input.knowledgeGaps.length > 0 ? input.knowledgeGaps.join("; ") : "none observed"}`,
    `Answered "I don't know": ${input.idkCount} time(s)`,
    `Hints/simpler reframings given: ${input.hintCount} time(s)`,
    `Brief answers: ${input.briefAnswerCount} of ${input.records.length}`,
    `Average score first half: ${input.firstHalfAvg.toFixed(2)}/5; second half: ${input.secondHalfAvg.toFixed(2)}/5`,
    "",
    "Questions the candidate struggled with:",
    ...(input.improvementQuestions.length > 0
      ? input.improvementQuestions.map((item) => `- ${item.topic}: ${item.question.slice(0, 200)} (issue: ${item.issue.slice(0, 120)})`)
      : ["none"]),
    "",
    "Sample of actual questions and answers from the interview:",
    sampleExcerpts(input),
    "",
    "Write the narrative JSON now.",
  ].join("\n");

  return {
    system: SYSTEM_PROMPT.replace("{mode}", MODE_INSTRUCTIONS[mode]),
    user,
  };
}
